Item.method_code:
/* globals arasTabs */
let searchText = '';

const textbox = document.getElementById('aras-es-toolbar-input');
if (textbox) {
	searchText = textbox.value;
}

const getLicensePage = '../Modules/aras.innovator.ES/Views/GetLicense.html';
const solutionMainPage = '../Solutions/ES/Views/Main.html';

let url = getLicensePage;
const esVersion = getFeatureVersion();

if (esVersion !== null && esVersion.includes('R')) {
	url = solutionMainPage;
	if (searchText !== '') {
		url += '?q=' + encodeURIComponent(searchText);
	}
}

const winName = 'es_' + Date.now();
arasTabs.open(url, winName, false);

function getFeatureVersion() {
	let itm = aras.newIOMItem('Variable', 'get');
	itm.setID('7CA8A4561F3147E4B94F2C245F026183');
	itm.setAttribute('select', 'value');
	itm = itm.apply();

	return itm.isError() ? null : itm.getProperty('value', null);
}
